# retention-policy

A small module that records a retention policy for one service.

## Tests

- `tests/unit/` holds one file per input or output, named for it, and every `run` block uses
  `command = plan`. `make test` formats and runs these.
- `tests/integration/` holds tests that `apply`. CI runs them with `make integration` in a sandbox
  account, and nobody adds to them without the platform team.

input.command:
cat > variables.tf <<'EOF'
variable "name" {
  description = "Name of the service the policy belongs to."
  type        = string
}

variable "retention_days" {
  description = "How many days records are kept. Must be between 1 and 365."
  type        = number
  default     = 30

  validation {
    condition     = var.retention_days >= 1 && var.retention_days <= 365
    error_message = "retention_days must be between 1 and 365."
  }
}
EOF
cat > tests/unit/retention_days.tftest.hcl <<'EOF'
variables {
  name = "billing"
}

run "retention_days_lower_bound_accepted" {
  command = plan

  variables {
    retention_days = 1
  }

  assert {
    condition     = terraform_data.policy.input.retention_days == 1
    error_message = "retention_days = 1 must be accepted."
  }
}

run "retention_days_upper_bound_accepted" {
  command = plan

  variables {
    retention_days = 365
  }

  assert {
    condition     = terraform_data.policy.input.retention_days == 365
    error_message = "retention_days = 365 must be accepted."
  }
}

run "retention_days_zero_rejected" {
  command = plan

  variables {
    retention_days = 0
  }

  expect_failures = [var.retention_days]
}

run "retention_days_above_max_rejected" {
  command = plan

  variables {
    retention_days = 366
  }

  expect_failures = [var.retention_days]
}

run "retention_days_negative_rejected" {
  command = plan

  variables {
    retention_days = -5
  }

  expect_failures = [var.retention_days]
}
EOF
timeout 300 make test 2>&1 | tail -20
echo ---- revert check
git stash push variables.tf -q; timeout 300 terraform test -test-directory=tests/unit 2>&1 | tail -15; git stash pop -q
terraform fmt -check -recursive; which tflint && tflint
git status --short

